//! `drift`: compare a live server's tool list with the metadata recorded at generation.
//!
//! Exits 0 when nothing changed and 5 when tools were added or removed or the endpoint
//! differs; it never writes anything. Messages say that the server changed or that the tool list
//! differs from the one recorded at generation, never that files are out of date: provenance
//! answers neither question about generated bytes (see `mcp_execution_core::provenance`).

use std::collections::BTreeSet;
use std::path::PathBuf;

use anyhow::{Context, Result};
use clap::Args;
use mcp_execution_core::ServerId;
use mcp_execution_core::cli::{ExitCode, OutputFormat};
use mcp_execution_core::provenance::{ConfigFingerprint, ToolDigest, ToolDigestEntry};
use mcp_execution_core::untrusted::sanitize_untrusted_inline;
use mcp_execution_introspector::{CacheScope, Discovery, Introspector, ListingHints, ToolInfo};
use mcp_execution_skill::scripts::{self, ScriptListing};
use serde::{Deserialize, Serialize};

use super::common::{
    ServerSource, SkillsDir, read_generated_metadata_async, resolve_server_config,
};
use super::generate::{generated_location, name_override};
use crate::cli::ServerFlags;

/// Largest number of tool names printed per list; the rest is reported as "and N more".
const MAX_PRINTED_NAMES: usize = 20;

/// Longest tool name printed, in characters, after sanitising.
const MAX_NAME_CHARS: usize = 128;

/// Options of the `drift` command.
#[derive(Debug, Args)]
pub struct DriftArgs {
    /// Server selection, transport, and timeout flags (shared with `introspect`)
    #[command(flatten)]
    pub flags: ServerFlags,

    /// Custom server name of the generated directory (same as `generate --name`)
    #[arg(long)]
    pub name: Option<String>,

    /// Base directory of the generated files (same as `generate --progressive-output`;
    /// default: ~/.claude/servers/)
    #[arg(long)]
    pub progressive_output: Option<PathBuf>,
}

/// Result of comparing a live server with the recorded generation provenance.
///
/// The endpoint is checked first: when the connection parameters differ, a tool difference is not
/// attributed to the server changing.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "outcome", rename_all = "snake_case")]
pub enum DriftOutcome {
    /// Endpoint and tool list match what was recorded.
    NoDrift,
    /// The config fingerprint differs: the recorded generation came from another endpoint.
    EndpointDiffers,
    /// The tool list differs from the recorded one.
    ToolsDiffer {
        /// Tools only the live server lists, sorted by name.
        added: Vec<String>,
        /// Tools only the recorded generation lists, sorted by name.
        removed: Vec<String>,
    },
}

impl DriftOutcome {
    /// Whether the outcome is anything other than [`DriftOutcome::NoDrift`].
    #[must_use]
    pub const fn is_drift(&self) -> bool {
        !matches!(self, Self::NoDrift)
    }
}

/// Compares recorded provenance with the live listing.
///
/// Uses the same fingerprint and digest functions `generate` records with, so equal inputs
/// always compare equal.
#[must_use]
pub fn compare(
    recorded_fingerprint: &ConfigFingerprint,
    recorded_digest: &ToolDigest,
    recorded_names: &[&str],
    live_fingerprint: &ConfigFingerprint,
    live_tools: &[ToolDigestEntry<'_>],
) -> DriftOutcome {
    if recorded_fingerprint != live_fingerprint {
        return DriftOutcome::EndpointDiffers;
    }
    if recorded_digest == &ToolDigest::compute(live_tools) {
        return DriftOutcome::NoDrift;
    }
    let recorded: BTreeSet<&str> = recorded_names.iter().copied().collect();
    let live: BTreeSet<&str> = live_tools.iter().map(|tool| tool.name).collect();
    DriftOutcome::ToolsDiffer {
        added: live
            .difference(&recorded)
            .map(ToString::to_string)
            .collect(),
        removed: recorded
            .difference(&live)
            .map(ToString::to_string)
            .collect(),
    }
}

/// Tool names printed for one side of the difference, bounded and sanitised.
#[derive(Debug, Serialize)]
struct NameList {
    names: Vec<String>,
    more: usize,
}

impl NameList {
    fn bounded(names: &[String]) -> Self {
        Self {
            names: names
                .iter()
                .take(MAX_PRINTED_NAMES)
                .map(|name| {
                    sanitize_untrusted_inline(name)
                        .chars()
                        .take(MAX_NAME_CHARS)
                        .collect()
                })
                .collect(),
            more: names.len().saturating_sub(MAX_PRINTED_NAMES),
        }
    }

    fn lines(&self, heading: &str, out: &mut Vec<String>) {
        if self.names.is_empty() {
            return;
        }
        out.push(format!("{heading}:"));
        out.extend(self.names.iter().map(|name| format!("  {name}")));
        if self.more > 0 {
            out.push(format!("  and {} more", self.more));
        }
    }
}

/// What gets printed: the verdict, the names, and the listing hints.
#[derive(Debug, Serialize)]
struct DriftReport {
    drift: bool,
    summary: &'static str,
    only_on_server: NameList,
    only_recorded: NameList,
    scripts_using_removed_tools: NameList,
    ttl_seconds: Option<u64>,
    cache_scope: Option<&'static str>,
    notices: Vec<&'static str>,
}

impl DriftReport {
    fn new(outcome: &DriftOutcome, hints: ListingHints, scripts: &[String]) -> Self {
        let (summary, added, removed): (&'static str, &[String], &[String]) = match outcome {
            DriftOutcome::NoDrift => (
                "no drift: the tool list matches the one recorded at generation",
                &[],
                &[],
            ),
            DriftOutcome::EndpointDiffers => (
                "the endpoint differs from the one recorded at generation; \
                 tool lists were not compared",
                &[],
                &[],
            ),
            DriftOutcome::ToolsDiffer { added, removed } => (
                "server changed: the tool list differs from the one recorded at generation",
                added,
                removed,
            ),
        };
        let mut notices = Vec::new();
        if hints.cache_scope == Some(CacheScope::Private) {
            notices.push("the listing may depend on credentials");
        }
        if matches!(outcome, DriftOutcome::ToolsDiffer { .. })
            && added.is_empty()
            && removed.is_empty()
        {
            notices.push("which tool changed cannot be determined from the recorded data");
        }
        Self {
            drift: outcome.is_drift(),
            summary,
            only_on_server: NameList::bounded(added),
            only_recorded: NameList::bounded(removed),
            scripts_using_removed_tools: NameList::bounded(scripts),
            ttl_seconds: hints.ttl.map(|ttl| ttl.as_secs()),
            cache_scope: hints.cache_scope.map(|scope| match scope {
                CacheScope::Public => "public",
                CacheScope::Private => "private",
            }),
            notices,
        }
    }

    fn text(&self) -> String {
        let mut lines = vec![self.summary.to_string()];
        self.only_on_server
            .lines("present on the server, not recorded", &mut lines);
        self.only_recorded
            .lines("recorded, not on the server", &mut lines);
        self.scripts_using_removed_tools
            .lines("saved scripts using a removed tool", &mut lines);
        lines.extend(self.notices.iter().map(ToString::to_string));
        if let Some(ttl) = self.ttl_seconds {
            lines.push(format!("server listing ttl: {ttl}s"));
        }
        if let Some(scope) = self.cache_scope {
            lines.push(format!("server listing cache scope: {scope}"));
        }
        lines.join("\n")
    }
}

/// Runs the `drift` command.
///
/// Always issues the live request; listing hints are reported, never used to skip it. Writes
/// nothing.
///
/// # Errors
///
/// Returns a classified error when the check could not run: invalid server selection, connection
/// or discovery failure, or a missing, oversized, unreadable or unsupported `_meta.json`.
pub async fn run(args: DriftArgs, format: OutputFormat) -> Result<ExitCode> {
    let DriftArgs {
        flags,
        name,
        progressive_output,
    } = args;
    let override_id = name_override(name.as_deref())?;
    let source = ServerSource::try_from(flags)?;
    let from_unvalidated_config_key =
        matches!(source, ServerSource::Config { .. }) && override_id.is_none();
    let (server_id, config) = resolve_server_config(source)?;
    let skill_id = override_id.unwrap_or_else(|| server_id.clone());
    let (_, server_dir) =
        generated_location(&skill_id, from_unvalidated_config_key, progressive_output)?;
    let recorded = read_generated_metadata_async(server_dir, &skill_id).await?;

    let Discovery { info, hints } = Introspector::new()
        .discover(server_id.clone(), &config)
        .await
        .with_context(|| format!("failed to connect to server '{server_id}'"))?;

    let live: Vec<ToolDigestEntry<'_>> = info.tools.iter().map(ToolInfo::digest_entry).collect();
    let recorded_names: Vec<&str> = recorded.tools.iter().map(|t| t.name.as_str()).collect();
    let outcome = compare(
        &recorded.provenance.config_fingerprint,
        &recorded.provenance.tool_digest,
        &recorded_names,
        &ConfigFingerprint::compute(&config),
        &live,
    );

    let scripts = match &outcome {
        DriftOutcome::ToolsDiffer { removed, .. } if !removed.is_empty() => {
            scripts_using(&skill_id, removed).await
        }
        _ => Vec::new(),
    };
    let report = DriftReport::new(&outcome, hints, &scripts);
    let exit = if outcome.is_drift() {
        ExitCode::CHECK_FAILED
    } else {
        ExitCode::SUCCESS
    };
    match format {
        OutputFormat::Json => crate::formatters::emit(&report, format, exit),
        OutputFormat::Text | OutputFormat::Pretty => {
            println!("{}", report.text());
            Ok(exit)
        }
    }
}

/// Names of the saved scripts of `server_id` that call any of the `removed` tools.
///
/// Best effort: a missing skill directory or unreadable scripts yield no names, since the drift
/// verdict does not depend on them.
async fn scripts_using(server_id: &ServerId, removed: &[String]) -> Vec<String> {
    let Ok(skills) = SkillsDir::resolve(None) else {
        return Vec::new();
    };
    let skill_dir = skills.skill(server_id);
    if !skill_dir.is_dir() {
        return Vec::new();
    }
    scripts::list(&skill_dir)
        .await
        .map_or_default(|listings| referencing(&listings, server_id, removed))
}

/// Names of the `listings` that call a `removed` tool of `server_id`, in listing order.
fn referencing(
    listings: &[ScriptListing],
    server_id: &ServerId,
    removed: &[String],
) -> Vec<String> {
    listings
        .iter()
        .filter(|listing| {
            listing.tools.iter().any(|tool| {
                tool.server == *server_id && removed.iter().any(|name| name == tool.tool.as_str())
            })
        })
        .map(|listing| listing.name.as_str().to_string())
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use mcp_execution_core::ServerConfig;
    use serde_json::json;

    fn fingerprint(command: &str) -> ConfigFingerprint {
        ConfigFingerprint::compute(
            &ServerConfig::builder()
                .command(command.to_string())
                .build()
                .unwrap(),
        )
    }

    fn entry<'a>(name: &'a str, schema: &'a serde_json::Value) -> ToolDigestEntry<'a> {
        ToolDigestEntry {
            name,
            description: "d",
            input_schema: schema,
            output_schema: None,
            annotations: None,
        }
    }

    #[test]
    fn equal_digest_is_no_drift() {
        let schema = json!({});
        let live = [entry("a", &schema)];
        let fp = fingerprint("x");
        let outcome = compare(&fp, &ToolDigest::compute(&live), &["a"], &fp, &live);
        assert_eq!(outcome, DriftOutcome::NoDrift);
    }

    #[test]
    fn different_endpoint_wins_over_tool_difference() {
        let outcome = compare(
            &fingerprint("x"),
            &ToolDigest::compute(&[]),
            &[],
            &fingerprint("y"),
            &[],
        );
        assert_eq!(outcome, DriftOutcome::EndpointDiffers);
    }

    #[test]
    fn names_are_split_into_added_and_removed() {
        let schema = json!({});
        let live = [entry("b", &schema), entry("a", &schema)];
        let fp = fingerprint("x");
        let outcome = compare(&fp, &ToolDigest::compute(&[]), &["a", "gone"], &fp, &live);
        assert_eq!(
            outcome,
            DriftOutcome::ToolsDiffer {
                added: vec!["b".to_string()],
                removed: vec!["gone".to_string()],
            }
        );
    }

    #[test]
    fn same_names_with_a_different_digest_is_undetermined() {
        let schema = json!({});
        let live = [entry("a", &schema)];
        let fp = fingerprint("x");
        let outcome = compare(&fp, &ToolDigest::compute(&[]), &["a"], &fp, &live);
        let report = DriftReport::new(&outcome, ListingHints::default(), &[]);
        assert!(report.text().contains("cannot be determined"));
    }

    #[test]
    fn printed_names_are_capped_with_a_remainder() {
        let names: Vec<String> = (0..25).map(|n| format!("t{n}")).collect();
        let list = NameList::bounded(&names);
        assert_eq!((list.names.len(), list.more), (20, 5));
    }

    #[test]
    fn only_scripts_calling_a_removed_tool_of_this_server_are_listed() {
        use mcp_execution_core::ToolName;
        use mcp_execution_skill::scripts::{RecipeName, ToolRef, WriteIntent};

        let listing = |name: &str, server: &str, tool: &str| ScriptListing {
            name: RecipeName::new(name).unwrap(),
            description: String::new(),
            tools: vec![ToolRef {
                server: ServerId::new(server).unwrap(),
                tool: ToolName::new(tool).unwrap(),
            }],
            writes: WriteIntent::ReadOnly,
        };
        let listings = [
            listing("hit", "s", "gone"),
            listing("other-tool", "s", "kept"),
            listing("other-server", "t", "gone"),
        ];
        let names = referencing(
            &listings,
            &ServerId::new("s").unwrap(),
            &["gone".to_string()],
        );
        assert_eq!(names, ["hit"]);
    }

    #[test]
    fn private_scope_warns_about_credentials() {
        let hints = ListingHints {
            ttl: None,
            cache_scope: Some(CacheScope::Private),
        };
        let report = DriftReport::new(&DriftOutcome::NoDrift, hints, &[]);
        assert!(report.text().contains("depend on credentials"));
    }
}
